/// `Post::class`, the `fileable_type` of post photos.
const POST_FILEABLE: &str = "App\\Models\\Post";

/// `SliceOfLife::class`, the `fileable_type` of slice covers.
const SLICE_FILEABLE: &str = "App\\Models\\SliceOfLife";

fn midnight(day: NaiveDate) -> Timestamp {
    Timestamp(day.and_time(NaiveTime::MIN))
}

/// The last second of `day` (stored datetimes have no fractions).
fn end_of_day(day: NaiveDate) -> Timestamp {
    Timestamp(day.and_hms_opt(23, 59, 59).expect("a valid time"))
}

/// `Str::limit($value, $limit)`: at most `limit` characters; a cut value
/// loses its trailing whitespace (`rtrim`) and ends with `...`.
fn limit(value: &str, limit: usize) -> String {
    if value.chars().count() <= limit {
        return value.to_owned();
    }
    let cut: String = value.chars().take(limit).collect();
    format!("{}...", cut.trim_end_matches([' ', '\t', '\n', '\r', '\0', '\x0B']))
}

/// `Str::wordCount`, PHP's `str_word_count` in the C locale: runs of ASCII
/// letters, `'` and `-`, where the string's first `'` or `-` and its last
/// `-` don't count.
fn word_count(s: &str) -> i64 {
    let b = s.as_bytes();
    if b.is_empty() {
        return 0;
    }
    let (mut p, mut e) = (0, b.len());
    if b[0] == b'\'' || b[0] == b'-' {
        p += 1;
    }
    if b[e - 1] == b'-' {
        e -= 1;
    }
    let mut count = 0;
    while p < e {
        let start = p;
        while p < e && (b[p].is_ascii_alphabetic() || b[p] == b'\'' || b[p] == b'-') {
            p += 1;
        }
        if p > start {
            count += 1;
        }
        p += 1;
    }
    count
}

/// `$post->files` of these posts.
fn post_files(post_ids: Vec<Id>) -> Condition {
    Condition::all().add(files::Column::FileableType.eq(POST_FILEABLE)).add(files::Column::FileableId.is_in(post_ids))
}

/// The cover files of these slices, as Q7 deletes them with the slices:
/// `file_cover_image_id`, and covers still attached to the slice.
fn slice_files(slices: &[slice_of_lives::Model]) -> Condition {
    Condition::any().add(files::Column::Id.is_in(slices.iter().filter_map(|s| s.file_cover_image_id))).add(
        Condition::all()
            .add(files::Column::FileableType.eq(SLICE_FILEABLE))
            .add(files::Column::FileableId.is_in(slices.iter().map(|s| s.id))),
    )
}

/// Deletes the bytes of `files` rows that are gone (E009) right away, rather
/// than at the next storage sweep.
async fn purge(state: &AppState, rows: &[files::Model]) {
    for f in rows {
        state.storage.delete(f.vault_id, &f.uuid).await;
    }
}

/// `$vault->journals()->findOrFail($id)`.
async fn find_journal(state: &AppState, vault_id: Uuid, journal_id: Id) -> ApiResult<journals::Model> {
    journals::Entity::find_by_id(journal_id)
        .filter(journals::Column::VaultId.eq(vault_id))
        .one(&state.db)
        .await?
        .ok_or_else(ApiError::not_found)
}

/// The journal and post of the path: 404 unless the post is in the journal.
async fn find_post(
    state: &AppState,
    vault_id: Uuid,
    journal_id: Id,
    post_id: Id,
) -> ApiResult<(journals::Model, posts::Model)> {
    let journal = find_journal(state, vault_id, journal_id).await?;
    let post = posts::Entity::find_by_id(post_id)
        .filter(posts::Column::JournalId.eq(journal.id))
        .one(&state.db)
        .await?
        .ok_or_else(ApiError::not_found)?;
    Ok((journal, post))
}

/// `$journal->slicesOfLife()->findOrFail($id)` (F1).
async fn find_slice(
    state: &AppState,
    vault_id: Uuid,
    journal_id: Id,
    slice_id: Id,
) -> ApiResult<(journals::Model, slice_of_lives::Model)> {
    let journal = find_journal(state, vault_id, journal_id).await?;
    let slice = journal_slice(state, journal.id, slice_id).await?.ok_or_else(ApiError::not_found)?;
    Ok((journal, slice))
}

async fn journal_slice(state: &AppState, journal_id: Id, slice_id: Id) -> ApiResult<Option<slice_of_lives::Model>> {
    Ok(slice_of_lives::Entity::find_by_id(slice_id)
        .filter(slice_of_lives::Column::JournalId.eq(journal_id))
        .one(&state.db)
        .await?)
}

fn check_name(v: &mut Validator, field: &str, name: &Option<String>) {
    if v.required(field, name) {
        v.max_len(field, name.as_deref(), 255);
    }
}

/// A PATCH of a required string: absent keeps `current`, present is
/// [`clean`]ed and must not be empty.
fn patched_name(v: &mut Validator, field: &str, value: Option<String>, current: &str) -> String {
    match value {
        Some(n) => {
            let n = clean(Some(n));
            check_name(v, field, &n);
            n.unwrap_or_default()
        }
        None => current.to_owned(),
    }
}

/// A PATCH of a nullable string: absent keeps `current`, `null` clears it.
fn patched_text(
    v: &mut Validator,
    field: &str,
    value: Option<Option<String>>,
    current: &Option<String>,
    max: usize,
) -> Option<String> {
    match value {
        Some(d) => {
            let d = clean(d);
            v.max_len(field, d.as_deref(), max);
            d
        }
        None => current.clone(),
    }
}

fn tag(t: tags::Model) -> Tag {
    Tag {
        id: t.id,
        vault_id: t.vault_id,
        name: t.name,
        slug: t.slug,
        posts_count: None,
        created_at: t.created_at.unwrap_or_else(crate::db::now),
        updated_at: t.updated_at.unwrap_or_else(crate::db::now),
    }
}

impl Journal {
    /// `JournalIndexViewHelper::dto`, with the date of the latest post.
    async fn load<C: ConnectionTrait>(db: &C, j: journals::Model) -> ApiResult<Journal> {
        let latest = posts::Entity::find()
            .filter(posts::Column::JournalId.eq(j.id))
            .order_by_desc(posts::Column::WrittenAt)
            .one(db)
            .await?;
        Ok(Journal {
            id: j.id,
            vault_id: j.vault_id,
            name: j.name,
            description: j.description,
            last_post_written_at: latest.map(|p| p.written_at.0.date()),
            created_at: j.created_at.unwrap_or_else(crate::db::now),
            updated_at: j.updated_at.unwrap_or_else(crate::db::now),
        })
    }
}

impl SliceOfLife {
    /// The slices with `SliceOfLifeHelper::getDateRange`'s oldest and newest
    /// post dates.
    async fn load_many<C: ConnectionTrait>(db: &C, slices: Vec<slice_of_lives::Model>) -> ApiResult<Vec<SliceOfLife>> {
        let mut ranges: HashMap<Id, (NaiveDate, NaiveDate)> = HashMap::new();
        if !slices.is_empty() {
            let posts = posts::Entity::find()
                .filter(posts::Column::SliceOfLifeId.is_in(slices.iter().map(|s| s.id)))
                .all(db)
                .await?;
            for p in posts {
                let Some(slice_id) = p.slice_of_life_id else { continue };
                let day = p.written_at.0.date();
                ranges.entry(slice_id).and_modify(|r| *r = (r.0.min(day), r.1.max(day))).or_insert((day, day));
            }
        }
        Ok(slices
            .into_iter()
            .map(|s| {
                let range = ranges.get(&s.id).copied();
                SliceOfLife {
                    id: s.id,
                    journal_id: s.journal_id,
                    name: s.name,
                    description: s.description,
                    file_cover_image_id: s.file_cover_image_id.map(|f| f.0),
                    oldest_post_written_at: range.map(|r| r.0),
                    newest_post_written_at: range.map(|r| r.1),
                    created_at: s.created_at.unwrap_or_else(crate::db::now),
                    updated_at: s.updated_at.unwrap_or_else(crate::db::now),
                }
            })
            .collect())
    }

    async fn load<C: ConnectionTrait>(db: &C, slice: slice_of_lives::Model) -> ApiResult<SliceOfLife> {
        Ok(Self::load_many(db, vec![slice]).await?.pop().expect("one slice"))
    }
}

impl PostSummary {
    /// The list form of each post, in their order: what the journal page,
    /// a slice of life page, the contact page's posts module and the
    /// calendar show of a post.
    pub async fn load_many<C: ConnectionTrait>(db: &C, posts: Vec<posts::Model>) -> ApiResult<Vec<PostSummary>> {
        if posts.is_empty() {
            return Ok(Vec::new());
        }
        let ids: Vec<Id> = posts.iter().map(|p| p.id).collect();
        let journal_ids: HashSet<Id> = posts.iter().map(|p| p.journal_id).collect();
        let journals: HashMap<Id, journals::Model> = journals::Entity::find()
            .filter(journals::Column::Id.is_in(journal_ids))
            .all(db)
            .await?
            .into_iter()
            .map(|j| (j.id, j))
            .collect();

        // `Post::excerpt`: the first section with content.
        let mut excerpts: HashMap<Id, String> = HashMap::new();
        let sections = post_sections::Entity::find()
            .filter(post_sections::Column::PostId.is_in(ids.clone()))
            .filter(post_sections::Column::Content.is_not_null())
            .order_by_asc(post_sections::Column::Position)
            .order_by_asc(post_sections::Column::Id)
            .all(db)
            .await?;
        for s in sections {
            if let Some(content) = s.content {
                excerpts.entry(s.post_id).or_insert_with(|| limit(&content, 200));
            }
        }

        // `$post->files->first()`.
        let mut photos: HashMap<Id, files::Model> = HashMap::new();
        for f in files::Entity::find().filter(post_files(ids)).order_by_asc(files::Column::Id).all(db).await? {
            if let Some(post_id) = f.fileable_id {
                photos.entry(post_id).or_insert(f);
            }
        }

        posts
            .into_iter()
            .map(|p| {
                let journal =
                    journals.get(&p.journal_id).ok_or_else(|| ApiError::internal("a post without journal"))?;
                Ok(PostSummary {
                    id: p.id,
                    journal: PostSummaryJournal { id: journal.id, name: journal.name.clone() },
                    slice_of_life_id: p.slice_of_life_id.map(|s| s.0),
                    title: value_or_null(p.title),
                    published: p.published,
                    written_at: p.written_at.0.date(),
                    excerpt: excerpts.remove(&p.id),
                    first_photo: photos.remove(&p.id).map(Into::into),
                    created_at: p.created_at.unwrap_or_else(crate::db::now),
                    updated_at: p.updated_at.unwrap_or_else(crate::db::now),
                })
            })
            .collect()
    }
}

