#[utoipa::path(
    patch,
    path = "/vaults/{vault_id}/journals/{journal_id}/posts/{post_id}",
    operation_id = "updateJournalPost",
    tag = "Journals",
    summary = "Edit a post's title, date or section contents",
    params(("vault_id" = uuid::Uuid, Path), ("journal_id" = i64, Path), ("post_id" = i64, Path)),
    request_body = PostUpdate,
    responses((status = 200, description = "The updated post.", body = Post), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R144"])), ("x-services" = json!(["UpdatePost"])))
)]
pub async fn update_journal_post(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, journal_id, post_id)): Path<(Uuid, Id, Id)>,
    Json(body): Json<PostUpdate>,
) -> ApiResult<Json<Post>> {
    let access = access::vault(&state, &id, vault_id, VaultPermission::Edit).await?;
    let (journal, post) = find_post(&state, vault_id, journal_id, post_id).await?;
    let mut v = Validator::new();
    let title = match body.title {
        Some(t) => clean(t),
        None => post.title.clone(),
    };
    v.max_len("title", title.as_deref(), 255);
    let mut sections = Vec::new();
    for (i, s) in body.sections.unwrap_or_default().into_iter().enumerate() {
        let id_field = format!("sections[{i}].id");
        let content_field = format!("sections[{i}].content");
        v.required(&id_field, &s.id);
        if v.required(&content_field, &s.content) {
            let content = s.content.and_then(clean);
            v.max_len(&content_field, content.as_deref(), 65535);
            sections.push(UpdatePostSection { id: s.id.unwrap_or(Id(0)), content: Some(content) });
        }
    }
    v.finish()?;
    // UpdatePost requires `sections` (PHP `required`) and skips entries
    // without `content`: a PATCH that changes no section sends one such.
    if sections.is_empty() {
        sections.push(UpdatePostSection { id: Id(0), content: None });
    }
    let written_at = body.written_at.unwrap_or_else(|| post.written_at.0.date());
    let tx = state.db.begin().await?;
    // F16: only UpdatePost; mentioned contacts change through their own operations.
    let post = UpdatePost {
        account_id: id.user.account_id,
        vault_id,
        author_id: id.user.id,
        journal_id: journal.id,
        post_id: post.id,
        title,
        sections,
        written_at: Some(written_at.format("%Y-%m-%d").to_string()),
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok(Json(post_view(&state, &access, journal, post).await?))
}

