#[utoipa::path(
    get,
    path = "/vaults/{vault_id}/journals/{journal_id}/slices/{slice_id}",
    operation_id = "getJournalSlice",
    tag = "Journals",
    summary = "Get a slice of life with its posts and the contacts they mention",
    params(("vault_id" = uuid::Uuid, Path), ("journal_id" = i64, Path), ("slice_id" = i64, Path)),
    responses((status = 200, description = "The slice of life.", body = SliceOfLifeDetail), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`).")),
    extensions(("x-permission" = json!("vault:view")), ("x-inventory" = json!(["R157", "R158"])), ("x-services" = json!([])))
)]
pub async fn get_journal_slice(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, journal_id, slice_id)): Path<(Uuid, Id, Id)>,
) -> ApiResult<Json<SliceOfLifeDetail>> {
    access::vault(&state, &id, vault_id, VaultPermission::View).await?;
    let (journal, slice) = find_slice(&state, vault_id, journal_id, slice_id).await?;
    let db = &state.db;
    let posts = posts::Entity::find()
        .filter(posts::Column::SliceOfLifeId.eq(slice.id))
        .order_by_desc(posts::Column::WrittenAt)
        .order_by_desc(posts::Column::Id)
        .all(db)
        .await?;

    // The contacts of the posts, each once, in the posts' order.
    let mut per_post: HashMap<Id, Vec<Uuid>> = HashMap::new();
    if !posts.is_empty() {
        let links = contact_post::Entity::find()
            .filter(contact_post::Column::PostId.is_in(posts.iter().map(|p| p.id)))
            .order_by_asc(contact_post::Column::ContactId)
            .all(db)
            .await?;
        for link in links {
            per_post.entry(link.post_id).or_default().push(link.contact_id);
        }
    }
    let mut contact_ids: Vec<Uuid> = Vec::new();
    for p in &posts {
        for c in per_post.remove(&p.id).unwrap_or_default() {
            if !contact_ids.contains(&c) {
                contact_ids.push(c);
            }
        }
    }
    let mut by_id: HashMap<Uuid, contacts::Model> = if contact_ids.is_empty() {
        HashMap::new()
    } else {
        contacts::Entity::live()
            .filter(contacts::Column::Id.is_in(contact_ids.clone()))
            .all(db)
            .await?
            .into_iter()
            .map(|c| (c.id, c))
            .collect()
    };
    let contacts: Vec<contacts::Model> = contact_ids.iter().filter_map(|c| by_id.remove(c)).collect();

    let s = SliceOfLife::load(db, slice).await?;
    Ok(Json(SliceOfLifeDetail {
        id: s.id,
        journal_id: s.journal_id,
        name: s.name,
        description: s.description,
        file_cover_image_id: s.file_cover_image_id,
        oldest_post_written_at: s.oldest_post_written_at,
        newest_post_written_at: s.newest_post_written_at,
        created_at: s.created_at,
        updated_at: s.updated_at,
        journal: SliceOfLifeDetailJournal { id: journal.id, name: journal.name },
        posts: PostSummary::load_many(db, posts).await?,
        contacts: ContactCard::load_many(db, contacts).await?,
    }))
}

