/// The operations of this module.
pub fn routes() -> OpenApiRouter<AppState> {
    OpenApiRouter::new()
        .routes(routes!(list_journals, create_journal))
        .routes(routes!(get_journal, update_journal, delete_journal))
        .routes(routes!(get_journal_overview))
        .routes(routes!(list_journal_photos))
        .routes(routes!(create_journal_post))
        .routes(routes!(get_journal_post, update_journal_post, delete_journal_post))
        .routes(routes!(record_journal_post_view))
        .routes(routes!(add_journal_post_contact, remove_journal_post_contact))
        .routes(routes!(upload_journal_post_photo))
        .routes(routes!(delete_journal_post_photo))
        .routes(routes!(create_journal_post_tag))
        .routes(routes!(assign_journal_post_tag, remove_journal_post_tag))
        .routes(routes!(set_journal_post_slice, clear_journal_post_slice))
        .routes(routes!(create_journal_post_metric))
        .routes(routes!(delete_journal_post_metric))
        .routes(routes!(list_journal_slices, create_journal_slice))
        .routes(routes!(get_journal_slice, update_journal_slice, delete_journal_slice))
        .routes(routes!(set_journal_slice_cover, delete_journal_slice_cover))
        .routes(routes!(list_journal_metrics, create_journal_metric))
        .routes(routes!(delete_journal_metric))
}

#[cfg(test)]
mod tests {
    #[test]
    fn counts_words_like_php() {
        assert_eq!(super::word_count("Hello fri3nd, you're looking good today!"), 7);
        assert_eq!(super::word_count("-well-known- words-"), 2);
        assert_eq!(super::word_count("'tis 'quoted'"), 2);
        assert_eq!(super::word_count("café naïve"), 3, "non-ASCII letters split words in the C locale");
        assert_eq!(super::word_count(" 42 "), 0);
        assert_eq!(super::word_count("a - b"), 3, "a lone inner hyphen is a word");
        assert_eq!(super::word_count(""), 0);
    }

    #[test]
    fn limits_like_laravel() {
        assert_eq!(super::limit("short", 200), "short");
        assert_eq!(super::limit("abcdef", 3), "abc...");
        assert_eq!(super::limit("ab  cdef", 4), "ab...");
        assert_eq!(super::limit("ééé", 2), "éé...");
    }
}
